import 'dart:convert';
import 'package:flutter_test/flutter_test.dart';
import 'package:kopitiam_mobile/services/sync_receipt.dart';
void main(){test('receipt matches immutable identity and digest',(){final rows=SyncReceiptGuard.prepare([{'Kode WO':'WO-1','ULP':'Koba','Tanggal':'15 September 2026','Status WO':'Selesai'}]),digest=rows.single['clientPayloadDigest'];expect(SyncReceiptGuard.verify({'success':true,'receipts':[{'committed':true,'kodeWo':'WO-1','ulp':'Koba','tanggal':'15 September 2026','payloadDigest':digest,'photo':null}]},rows),isTrue);expect(SyncReceiptGuard.verify({'success':true,'receipts':[]},rows),isFalse);});test('photo receipt requires Drive id and matching digest',(){final photo=base64Encode([255,216,255,217]),rows=SyncReceiptGuard.prepare([{'Kode WO':'WO-1','ULP':'Koba','Tanggal':'15 September 2026','fotoSesudahBase64':photo}]),row=rows.single;expect(SyncReceiptGuard.verify({'success':true,'receipts':[{'committed':true,'kodeWo':'WO-1','ulp':'Koba','tanggal':'15 September 2026','payloadDigest':row['clientPayloadDigest'],'photo':{'fileId':'drive-1','digest':row['clientPhotoDigest']}}]},rows),isTrue);});}
